+        Operator operator = operator(grouping, op, dataType);
+        Page page = page(grouping, blockType);
+        for (int i = 0; i < opCount; i++) {
+            operator.addInput(page);
+        }
+        operator.finish();
+        checkExpected(grouping, op, blockType, dataType, operator.getOutput(), opCount);
